/*
 * Common and shared styles
 */

/* First cells are aligned right and top by default */
.__toc_row_3cell td:nth-child(1) {
	vertical-align: top;
	text-align: right;
	white-space: nowrap;
}

/* The second cell is the "main" cell */
.__toc_row_3cell td:nth-child(2) {
	vertical-align: top;
	padding-left: 1em;
	width: 100%;
}

/* The last cell is the page number */
.__toc_row_3cell td:nth-child(2) {
	vertical-align: bottom;
	text-align: right;
	padding-left: 1em;
}

